def compute(vars):
    cost = vars["v1"]
    period = vars["v2"]

    if period == 0:
        return None

    average_per_year = cost / period

    return {
        "value": average_per_year,
        "trace": {
            "unrecognized_compensation_cost": cost,
            "weighted_average_recognition_period": period,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "currency per year"
            }
        }
    }
